// Return the byte-wise crc32c of data[0,n) with the given initial crc value, but in
// little-endian form.
uint32_t crc = init_crc;
for (size_t i = 0; i < n; i++) {
  // Process each byte of the input data using the CRC table.
  const uint8_t* p = reinterpret_cast<const uint8_t*>(data);
  uint8_t byte = p[i];
  // Update the CRC value using the byte extension table.
  crc = crc32c_Extend(crc, &byte, 1);
}
return crc;

